mapper.select:
SELECT id, household_id, actor_account_id, subject_account_id,
       action, outcome, detail, ip_address, request_id, created_at
FROM audit_log


        AND household_id = #{householdId, typeHandler=com.zija.system.internal.persistence.PostgresUuidTypeHandler}


        AND created_at >= #{from}


        AND created_at <= #{to}


        AND action = #{action}


        AND actor_account_id = #{actorAccountId, typeHandler=com.zija.system.internal.persistence.PostgresUuidTypeHandler}


        AND outcome = #{outcome}


ORDER BY created_at DESC
